package com.yuegang.zhihui.training.api;
import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.training.application.TrainingLearningRecordService;import com.yuegang.zhihui.training.security.TrainingUserResolver;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/training/learning")public final class TrainingLearningRecordController{private final TrainingLearningRecordService service;private final TrainingUserResolver users;public TrainingLearningRecordController(TrainingLearningRecordService service,TrainingUserResolver users){this.service=service;this.users=users;}@PutMapping("/position")ApiResponse<Map<String,Boolean>>position(@Valid@RequestBody ReadingPositionRequest body,HttpServletRequest request){service.recordPosition(users.resolve(request),body);return ok(Map.of("recorded",true),request);}@GetMapping("/assignments/{id}/chapters")ApiResponse<List<ChapterProgressView>>progress(@PathVariable String id,HttpServletRequest request){return ok(service.progress(users.resolve(request),id),request);}@GetMapping("/assignments/{id}/attempts")ApiResponse<List<QuizAttemptDetailView>>attempts(@PathVariable String id,HttpServletRequest request){return ok(service.attempts(users.resolve(request),id),request);}@GetMapping("/admin/analytics")ApiResponse<TrainingAnalyticsView>analytics(HttpServletRequest request){users.requirePermission(request,"training:statistics:read");return ok(service.analytics(),request);}private static<T>ApiResponse<T>ok(T data,HttpServletRequest request){return ApiResponse.success(data,TraceIdResolver.resolve(request));}}
